// app/page.tsx — composant serveur
import Compteur from "./compteur";
export default function Page() {
  return <main><h1>Bibliothèque</h1><p>Page rendue par le serveur.</p><Compteur /></main>;
}

// app/compteur.tsx — seul ce composant est interactif
"use client";
import { useState } from "react";
export default function Compteur() {
  const [n, setN] = useState(0);
  return <button type="button" onClick={() => setN(n + 1)}>Lectures : {n}</button>;
}
